DO $$ BEGIN CREATE TEMP TABLE IF NOT EXISTS _p AS SELECT DISTINCT po.* FROM supplier_invoices s CROSS JOIN LATERAL (SELECT public._sinv_po(s) AS po_id) x JOIN purchase_orders po ON po.id = x.po_id WHERE po.job_id IS NULL; RAISE EXCEPTION 'PROBE5 %', (SELECT string_agg(t,'|') FROM (SELECT coalesce(status,'')||'/'||coalesce(purpose,'')||'='||count(*) t FROM _p GROUP BY status,purpose ORDER BY count(*) DESC LIMIT 8) z); END $$;
